# -*- coding: utf-8 -*-
"""المبيعات + ابتكارات التسويق ودراسات السوق."""
from biz_tools import F, S, add, CATS, T
OL="function ol(a){return'<ol>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'}"

add('sales-pipeline-forecast','sales','📈','متوقّع المبيعات من خط الصفقات','توقع مرجّح بالاحتمالات لكل مرحلة وهل ستحقق الهدف.',
 [F('d','الصفقات (اسم | القيمة | المرحلة: جديد/تأهيل/عرض/تفاوض/إغلاق)','textarea','شركة أ | 50000 | عرض\nشركة ب | 30000 | تفاوض\nشركة ج | 80000 | تأهيل\nشركة د | 20000 | إغلاق\nشركة هـ | 40000 | جديد',r=6),F('t','هدف الفترة','n',120000),F('w','مبيعات محققة حتى الآن','n',25000)],
 r'''function compute(v){const P={'جديد':0.1,'تأهيل':0.25,'عرض':0.5,'تفاوض':0.7,'إغلاق':0.9};const L=lines(v.d).map(r=>({n:r[0],a:num(r[1]),s:r[2],p:P[r[2]]||0.1}));const w=L.reduce((s,x)=>s+x.a*x.p,0),tot=L.reduce((s,x)=>s+x.a,0),fc=v.w+w,gap=v.t-fc;return tbl(['الصفقة','القيمة','المرحلة','الاحتمال','القيمة المرجحة'],L.map(x=>[x.n,f(x.a),x.s,x.p*100+'%',f(x.a*x.p)]))+kpis([kpi('إجمالي الخط',f(tot)),kpi('توقع مرجح',f(w)),kpi('التوقع الكلي',f(fc),fc>=v.t?'good':'bad'),kpi('الفجوة',f(Math.max(gap,0)),gap>0?'bad':'good'),kpi('تغطية الخط للفجوة',gap>0?f(tot/gap,1)+'x':'—')])+rec([gap>0?'تحتاج خط صفقات بـ 3 أضعاف الفجوة تقريبًا: زد التنقيب.':'الهدف متوقع التحقق، ركّز على إغلاق الصفقات المتقدمة.','الاحتمالات افتراضية: عدّلها من بياناتك الفعلية.'])}''')

add('sales-commission-calculator','sales','💸','حاسبة العمولات بشرائح','عمولة تصاعدية حسب نسبة تحقيق الهدف مع مسرّعات.',
 [F('q','هدف المبيعات','n',100000),F('s','المبيعات الفعلية','n',130000),F('r1','عمولة حتى 100% من الهدف %','n',3),F('r2','عمولة ما فوق الهدف (مسرّع) %','n',5),F('b','راتب أساسي','n',6000)],
 r'''function compute(v){const base=Math.min(v.s,v.q),over=Math.max(0,v.s-v.q),c1=base*v.r1/100,c2=over*v.r2/100,tot=v.b+c1+c2;return kpis([kpi('نسبة التحقيق',f(v.s/v.q*100,1)+'%',v.s>=v.q?'good':'bad'),kpi('عمولة الشريحة 1',f(c1)),kpi('عمولة المسرّع',f(c2),'good'),kpi('إجمالي الدخل',f(tot),'good')])+rec(['المسرّع فوق الهدف يحفّز تجاوز المستهدف.','اربط العمولة بالتحصيل لا بالفوترة فقط.'])}''')

add('lead-scoring-model','sales','🎯','نموذج تأهيل العملاء المحتملين (Lead Scoring)','درجة لكل عميل محتمل وقرار: اتصل الآن/رعاية/أرشفة.',
 [F('d','العملاء (اسم | ميزانية 1-5 | صلاحية قرار 1-5 | حاجة 1-5 | وقت الشراء 1-5 | تفاعل 1-5)','textarea','أحمد | 4 | 5 | 4 | 3 | 5\nسارة | 2 | 3 | 5 | 2 | 3\nخالد | 5 | 2 | 3 | 4 | 4\nنورة | 1 | 1 | 2 | 1 | 1',r=6)],
 r'''function compute(v){const W=[0.25,0.2,0.25,0.15,0.15];const R=lines(v.d).map(r=>{const s=[1,2,3,4,5].map((i,k)=>num(r[i])*W[k]).reduce((a,b)=>a+b,0)/5*100;return[r[0],s]}).sort((a,b)=>b[1]-a[1]);return tbl(['العميل','الدرجة','القرار'],R.map(r=>[r[0],f(r[1],0),r[1]>=70?'🔥 اتصل اليوم':r[1]>=45?'🌱 رعاية':'🗄️ أرشفة']))+rec(['حدّث الأوزان من صفقاتك المغلقة فعلًا.','رد على الساخنين خلال ساعة.'])}''')

add('cac-payback-calculator','sales','⏱️','حاسبة تكلفة الاكتساب وفترة الاسترداد','CAC وفترة استرداد التكلفة وقيمة العميل.',
 [F('m','إنفاق التسويق','n',30000),F('s','إنفاق المبيعات (رواتب وعمولات)','n',50000),F('n','عملاء جدد','n',40),F('a','متوسط الإيراد الشهري للعميل','n',900),F('g','هامش الربح %','n',60),F('ch','فقد العملاء الشهري %','n',4)],
 r'''function compute(v){const cac=(v.m+v.s)/v.n,mp=v.a*v.g/100,pb=cac/mp,ltv=mp/(v.ch/100);return kpis([kpi('CAC',f(cac)),kpi('ربح العميل شهريًا',f(mp)),kpi('فترة الاسترداد (شهر)',f(pb,1),pb<=12?'good':'bad'),kpi('LTV',f(ltv)),kpi('LTV:CAC',f(ltv/cac,1)+'x',ltv/cac>=3?'good':'bad')])+rec([pb>12?'الاسترداد أطول من 12 شهرًا: راجع القنوات الأغلى.':'استرداد صحي.','خفّض الفقد قبل زيادة الإنفاق.'])}''')

add('sales-script-generator','sales','📞','مولّد نص مكالمة بيع','نص مكالمة بخمس مراحل: افتتاح، اكتشاف، عرض، اعتراض، إغلاق.',
 [F('p','المنتج','text','نظام محاسبة سحابي'),F('c','العميل المستهدف','text','أصحاب المتاجر الصغيرة'),F('b','الفائدة الأقوى','text','توفير 10 ساعات أسبوعيًا'),F('o','أكثر اعتراض','text','السعر')],
 r'''function compute(v){return ol(['الافتتاح: «مرحبًا [الاسم]، معك [اسمك]. أتواصل مع '+v.c+' لأن كثيرين يشتكون من الوقت الضائع. هل تسمح بدقيقتين؟»','الاكتشاف: «كيف تتعامل حاليًا مع هذا الأمر؟ ما أكثر ما يزعجك؟ كم يكلفك ذلك شهريًا؟»','العرض: «'+v.p+' يعطيك '+v.b+'. مثال: عميل مشابه حقق ... خلال ... »','الاعتراض ('+v.o+'): «أفهمك. لو قارنا '+v.o+' بالقيمة التي ستحصل عليها، خلال شهر سيغطي نفسه. هل أبدأ بتجربة؟»','الإغلاق: «هل يناسبك أن نبدأ الأحد أم الثلاثاء؟» ثم لخّص الخطوة التالية.'])+aiOut('اكتب نص مكالمة بيع محترف بالعربية لبيع '+v.p+' إلى '+v.c+' مع الفائدة '+v.b+' ومعالجة اعتراض '+v.o+' وثلاثة أسئلة اكتشاف.')}'''+OL)

add('objection-handler-generator','sales','🛡️','مولّد ردود اعتراضات العملاء','ردود جاهزة على أشهر الاعتراضات بإطار تأكيد-تفهم-حل.',
 [F('p','المنتج','text','دورة تدريبية'),F('v','ميزتك الأقوى','text','شهادة معتمدة ودعم مدى الحياة')],
 r'''function compute(v){const O=[['غالي','أتفهم أن السعر مهم. لننظر للعائد: '+v.v+'، وبالتقسيط تصبح التكلفة صغيرة شهريًا.'],['أفكر','طبيعي. ما الذي تحتاج توضيحه لتقرر؟ يمكنني إرسال ملخص يجيب ذلك.'],['عند المنافس أرخص','قارن الشامل: '+v.v+'. الرخيص قد يكلّف أكثر لاحقًا.'],['ليس الوقت المناسب','ما الذي سيتغير بعد شهر؟ يمكننا حجز مكانك الآن وبدء لاحقًا.'],['لا أثق بالنتيجة','معك حق في الحذر. لدينا ضمان واستشهادات عملاء، ونبدأ بتجربة صغيرة.']];return tbl(['الاعتراض','الرد المقترح لـ '+v.p],O)+aiOut('اكتب ردودًا مقنعة بالعربية على اعتراضات عملاء '+v.p+' مع ميزتنا: '+v.v)}''')

add('discount-impact-analyzer','sales','🏷️','محلل أثر الخصم على الربح','كم يجب أن تزيد الكمية لتعويض خصم يمنحه البائع؟',
 [F('p','السعر','n',500),F('c','التكلفة','n',300),F('d','الخصم %','n',10),F('q','الكمية الحالية','n',200)],
 r'''function compute(v){const m0=v.p-v.c,m1=v.p*(1-v.d/100)-v.c;if(m1<=0)return'<b>الخصم يلغي الربح بالكامل.</b>';const q=v.q*m0/m1;return kpis([kpi('هامش بعد الخصم',f(m1),m1<m0?'bad':'good'),kpi('كمية التعادل',f(Math.ceil(q),0)),kpi('زيادة لازمة',f((q/v.q-1)*100,1)+'%','bad')])+rec(['الخصم بنسبة '+v.d+'% يتطلب زيادة '+f((q/v.q-1)*100,0)+'% في الكمية لتبقى مكانك.','اعرض مزايا مضافة بدل الخصم المباشر إن أمكن.'])}''')

add('quota-capacity-planner','sales','🧮','مخطط طاقة فريق المبيعات','كم مندوبًا تحتاج لتحقيق هدفك؟',
 [F('t','هدف المبيعات السنوي','n',3000000),F('q','متوسط إنتاج المندوب السنوي','n',600000),F('a','نسبة تحقيق المندوبين المتوقعة %','n',80),F('r','معدل دوران المندوبين %','n',20),F('ramp','أشهر تأهيل المندوب الجديد','n',3)],
 r'''function compute(v){const eff=v.q*v.a/100,n=Math.ceil(v.t/eff),hire=Math.ceil(n*v.r/100);return kpis([kpi('إنتاج فعلي للمندوب',f(eff)),kpi('مندوبون لازمون',f(n,0),'good'),kpi('توظيف تعويضي سنويًا',f(hire,0))])+rec(['المندوب الجديد ينتج أقل خلال '+v.ramp+' أشهر: أضف 10-15% احتياطًا.'])}''')

add('customer-segmentation-matrix','market','🧩','مصفوفة تجزئة السوق','قارن الشرائح بحجمها ونموّها وتنافسها واختر الأولى.',
 [F('s','الشرائح (اسم | حجم 1-10 | نمو 1-10 | منافسة 1-10 (10 شديدة) | ملاءمتنا 1-10)','textarea','شباب جامعيون | 7 | 8 | 6 | 7\nأسر | 8 | 5 | 8 | 6\nشركات صغيرة | 5 | 7 | 4 | 9',r=5)],
 r'''function compute(v){const R=lines(v.s).map(r=>{const sc=num(r[1])*0.25+num(r[2])*0.25+(11-num(r[3]))*0.2+num(r[4])*0.3;return[r[0],sc]}).sort((a,b)=>b[1]-a[1]);return tbl(['الشريحة','درجة الجاذبية'],R.map(r=>[r[0],f(r[1],2)]))+rec(['الشريحة الأولى: '+(R[0]?R[0][0]:'-'),'استهدف شريحة واحدة أولًا ثم توسع.'])}''')
CATS['market']=('🔬','دراسات السوق','حجم السوق والمنافسون والشرائح والاستبيانات والتسعير ونية الشراء.')

add('van-westendorp-pricing','market','💲','تحليل حساسية السعر Van Westendorp','نطاق السعر المقبول من إجابات العملاء.',
 [F('a','أسعار «رخيص جدًا لدرجة الشك» (فاصلة)','text','20,25,30,25,35'),F('b','أسعار «رخيص/صفقة»','text','40,45,50,55,50'),F('c','أسعار «غالٍ لكن ممكن»','text','70,75,80,85,90'),F('d','أسعار «غالٍ جدًا»','text','100,110,120,115,130')],
 r'''function compute(v){const m=s=>{const a=s.split(',').map(Number).filter(x=>!isNaN(x));return a.reduce((x,y)=>x+y,0)/(a.length||1)};const A=m(v.a),B=m(v.b),C=m(v.c),D=m(v.d);return kpis([kpi('أدنى سعر مقبول',f(B)),kpi('سعر مقبول مثالي',f((B+C)/2),'good'),kpi('أعلى سعر مقبول',f(C)),kpi('حد الرفض',f(D),'bad')])+rec(['سعر أقل من '+f(A)+' يثير الشك في الجودة.','اختبر السعر المثالي مع عينة 100 عميل على الأقل.'])}''')

add('nps-csat-calculator','market','😊','حاسبة NPS و CSAT','مؤشر صافي المروّجين ورضا العملاء من نتائج استبيانك.',
 [F('p','مروّجون (9-10)','n',120),F('pa','محايدون (7-8)','n',60),F('d','منتقدون (0-6)','n',40),F('s','راضون (4-5) CSAT','n',170),F('t','إجمالي ردود CSAT','n',200)],
 r'''function compute(v){const n=v.p+v.pa+v.d,nps=(v.p-v.d)/n*100,cs=v.s/v.t*100;return kpis([kpi('NPS',f(nps,0),nps>=50?'good':nps<0?'bad':''),kpi('CSAT',f(cs,0)+'%',cs>=80?'good':'bad'),kpi('مروّجون',f(v.p/n*100,0)+'%'),kpi('منتقدون',f(v.d/n*100,0)+'%','bad')])+rec([nps<30?'ركّز على أسباب المنتقدين بالاتصال بهم.':'استفد من المروّجين: اطلب منهم تقييمات وإحالات.','قِس كل ربع لرصد الاتجاه.'])}''')

add('market-share-calculator','market','🥧','حاسبة الحصة السوقية والنمو','حصتك الحالية وكم تحتاج لزيادتها.',
 [F('m','حجم السوق السنوي','n',50000000),F('y','مبيعاتك','n',3000000),F('t','حصة مستهدفة %','n',10),F('g','نمو السوق %','n',8)],
 r'''function compute(v){const sh=v.y/v.m*100,nm=v.m*(1+v.g/100),need=nm*v.t/100;return kpis([kpi('حصتك الحالية',f(sh,1)+'%'),kpi('السوق بعد سنة',f(nm)),kpi('المبيعات المطلوبة',f(need)),kpi('نمو لازم',f((need/v.y-1)*100,1)+'%','good')])+rec(['جزء من النمو يأتي من نمو السوق نفسه: '+f(v.g,0)+'%.'])}''')

add('conversion-funnel-diagnoser','marketing','🩺','مشخّص قمع التحويل','أين الخلل؟ يقارن مراحلك بمتوسطات مرجعية.',
 [F('v','زوار','n',10000),F('l','مهتمون (تسجيل/سلة)','n',800),F('o','عروض/بدء دفع','n',300),F('s','مبيعات','n',120)],
 r'''function compute(v){const S=[['زائر→مهتم',v.l/v.v*100,6],['مهتم→بدء دفع',v.o/v.l*100,40],['بدء دفع→بيع',v.s/v.o*100,45]];return tbl(['المرحلة','نسبتك %','مرجع %','التشخيص'],S.map(s=>[s[0],f(s[1],1),s[2],s[1]<s[2]*0.7?'🔴 خلل':s[1]<s[2]?'🟡 تحسين':'🟢 جيد']))+rec(['ابدأ بأضعف مرحلة؛ الزيادة فيها أكبر أثرًا.'])}''')

add('email-campaign-calculator','marketing','✉️','حاسبة حملات البريد والواتساب','الفتح والنقر والطلبات والإيراد وتكلفة الطلب.',
 [F('n','حجم القائمة','n',5000),F('o','معدل الفتح %','n',30),F('c','النقر من الفاتحين %','n',8),F('cr','تحويل النقر %','n',4),F('a','متوسط الطلب','n',200),F('k','تكلفة الحملة','n',300)],
 r'''function compute(v){const op=v.n*v.o/100,cl=op*v.c/100,ord=cl*v.cr/100,rev=ord*v.a;return kpis([kpi('فتح',f(op,0)),kpi('نقرات',f(cl,0)),kpi('طلبات',f(ord,1)),kpi('الإيراد',f(rev),'good'),kpi('ROI',f((rev-v.k)/v.k*100,0)+'%',rev>v.k?'good':'bad')])+rec(['عنوان واضح وقصير يرفع الفتح.','قسّم القائمة حسب السلوك.'])}''')

add('seo-traffic-forecast','marketing','🔍','متوقّع زيارات SEO من الكلمات','تقدير زيارات الصفحة حسب الترتيب وحجم البحث.',
 [F('k','الكلمات (كلمة | بحث شهري | ترتيب متوقع)','textarea','حاسبة ضريبة | 12000 | 3\nنموذج عرض سعر | 4000 | 5\nأدوات محاسبة | 2500 | 8',r=5),F('c','تحويل الزيارة لعميل %','n',2)],
 r'''function compute(v){const CTR=[0,31,24,18,13,9,7,5,4,3,2.5];const R=lines(v.k).map(r=>{const rk=Math.min(10,Math.max(1,Math.round(num(r[2])))),t=num(r[1])*CTR[rk]/100;return[r[0],f(num(r[1]),0),rk,f(t,0)]});const tot=R.reduce((a,r)=>a+num(String(r[3]).replace(/,/g,'')),0);return tbl(['الكلمة','البحث','الترتيب','زيارات متوقعة'],R)+kpis([kpi('إجمالي الزيارات',f(tot,0),'good'),kpi('عملاء متوقعون',f(tot*v.c/100,1))])+rec(['نسب النقر تقريبية من دراسات عامة.','حسّن العناوين والأوصاف لرفع CTR.'])}''')
